export const messages: Record<UiLanguage, Dictionary> = {
  en: { ...generatedMessages.en, ...en },
  fr: { ...generatedMessages.fr, ...fr },
  es: { ...generatedMessages.es, ...es },
  de: { ...generatedMessages.de, ...de },
  it: { ...generatedMessages.it, ...it },
};

export function interpolate(template: string, variables?: Record<string, string | number>) {
  if (!variables) return template;
  return template.replace(/\{(\w+)\}/g, (match, key) =>
    Object.prototype.hasOwnProperty.call(variables, key) ? String(variables[key]) : match,
  );
}
